/// Delivers one typed notification response to the application, or explains why it cannot.
fn deliver_response(
    sender: &mpsc::UnboundedSender<SystemNotificationResponse>,
    tag: &SharedString,
    response: &NotificationResponse,
    action_ids: &HashMap<String, SharedString>,
) {
    let action_id = match response {
        // The XDG protocol reports a body click as the reserved `default` action.
        NotificationResponse::Default => response_action_id(DEFAULT_ACTION, action_ids),
        NotificationResponse::Action(transport_id) => response_action_id(transport_id, action_ids),
        // A close carries no action, and the XDG protocol has no inline reply.
        NotificationResponse::Closed(_) | NotificationResponse::Reply(_) => return,
    };
    let Some(action_id) = action_id else {
        log::warn!("system notification returned unknown action {response:?}");
        return;
    };
    sender
        .unbounded_send(SystemNotificationResponse {
            tag: tag.clone(),
            action_id,
        })
        .ok();
}

